const body = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};
const ip = ((headers['x-forwarded-for'] || '').toString().split(',')[0] || '').trim().slice(0, 64);

const name = (body.name || '').toString().trim().replace(/[<>]/g, '').slice(0, 100);
const email = (body.email || '').toString().trim().toLowerCase().slice(0, 254);
const rawPassword = (body.password || '').toString();

if (!name || !email || !rawPassword) {
  throw new Error('Name, email, and password are required.');
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Enter a valid email address.');
if (rawPassword.length < 10) throw new Error('Password must be at least 10 characters.');
if (rawPassword.length > 72) throw new Error('Password must be 72 characters or fewer.');

const bcrypt = require('bcryptjs');
const salt = bcrypt.genSaltSync(10);
const passwordHash = bcrypt.hashSync(rawPassword, salt);

// New accounts wait for an admin to approve them (Settings > Users > Reactivate) — otherwise anyone who finds
// the sign-up page gets a working rep login. The very first account (no active admin yet) is activated at once.
// At most 5 sign-up attempts per IP per hour.
const sqlQuery = `
  WITH recent AS (
    SELECT count(*)::int AS c FROM login_attempts WHERE kind = 'signup' AND $4 <> '' AND ip = $4 AND created_at > now() - interval '1 hour'
  ), logged AS (
    INSERT INTO login_attempts (kind, key, ip) VALUES ('signup', $2, $4) RETURNING 1
  ), ins AS (
    INSERT INTO users (name, email, password_hash, role, active, created_at, updated_at)
    SELECT $1, $2, $3, 'user', NOT EXISTS (SELECT 1 FROM users WHERE role = 'admin' AND active), NOW(), NOW()
    WHERE (SELECT c FROM recent) < 5
    ON CONFLICT (email) DO NOTHING
    RETURNING id, name, email, role, active, created_at
  )
  SELECT ins.id, ins.name, ins.email, ins.role, ins.active, ins.created_at, (SELECT c FROM recent) >= 5 AS limited
  FROM (SELECT 1) x LEFT JOIN ins ON true;
`;

return [{
  json: {
    sqlQuery,
    queryParams: [name, email, passwordHash, ip]
  }
}];

const item = $input.first().json;

if (item.limited) {
  return [{ json: { success: false, message: 'Too many sign-up attempts. Please try again later.' } }];
}
// Same message whether the email already exists or the insert failed, so sign-up can't be used to find out
// which emails have accounts.
if (item.error || !item.id) {
  return [{ json: { success: false, message: 'Could not create the account. If you already have one, sign in instead.' } }];
}

return [{
  json: {
    success: true,
    pending: item.active === false,
    message: item.active === false
      ? 'Account created. An administrator needs to approve it before you can sign in.'
      : 'Account created successfully!',
    user: {
      id: item.id,
      name: item.name,
      email: item.email,
      role: item.role
    }
  }
}];

const body = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};
const email = (body.email || '').toString().trim().toLowerCase().slice(0, 254);
const password = (body.password || '').toString().slice(0, 200);
// First address in x-forwarded-for is the real client when the request came through the tunnel.
const ip = ((headers['x-forwarded-for'] || '').toString().split(',')[0] || '').trim().slice(0, 64);

// One query that also returns how many recent failed attempts there are for this email and this IP.
// LEFT JOIN from a dummy row so an unknown email still gets a result row (and the counts).
const sqlQuery = `
  SELECT u.id, u.name, u.email, u.password_hash, u.role, u.active, u.theme_header_color, u.theme_main_color, u.theme_accent_color,
    (SELECT count(*) FROM login_attempts la WHERE la.kind = 'login' AND la.key = $1 AND la.created_at > now() - interval '15 minutes')::int AS email_failures,
    (SELECT count(*) FROM login_attempts la WHERE la.kind = 'login' AND $2 <> '' AND la.ip = $2 AND la.created_at > now() - interval '15 minutes')::int AS ip_failures
  FROM (SELECT $1::text AS e) d
  LEFT JOIN users u ON u.email = d.e
  LIMIT 1;
`;

return [{
  json: {
    rawPassword: password,
    email,
    ip,
    rememberMe: body.remember_me === true || body.remember_me === 'true',
    sqlQuery,
    queryParams: [email, ip]
  }
}];

const bcrypt = require('bcryptjs');
const dbResult = $input.first().json;
const login = $('Format Login Query').first().json;
const rawPassword = login.rawPassword;

// Lockout: 5 failed attempts per email, or 20 per IP, in 15 minutes. Checked before the password so a
// guesser gets no further information while locked.
if ((dbResult.email_failures || 0) >= 5 || (dbResult.ip_failures || 0) >= 20) {
  return [{ json: { success: false, locked: true, message: 'Too many failed attempts. Please wait 15 minutes and try again.' } }];
}

// Always run one bcrypt comparison, even for an unknown email, so response time doesn't reveal which emails exist.
const DUMMY_HASH = '$2a$10$CwTycUXWue0Thq9StjUM0uJ8.pZrRJ0xkZ0qkp3PzWtpVvQKJHzYa';
const hash = dbResult.id && dbResult.password_hash ? dbResult.password_hash : DUMMY_HASH;
const isPasswordValid = bcrypt.compareSync(rawPassword, hash);

if (!dbResult.id || !dbResult.active || !isPasswordValid) {
  return [{ json: { success: false, failed: true, message: 'Invalid credentials or account inactive.' } }];
}

// "Remember me" keeps the session for 7 days; otherwise it expires after 24 hours.
// The session token itself is generated by the database (gen_random_uuid, cryptographically secure) in Insert Session.
const TTL_MS = (login.rememberMe === true ? 7 : 1) * 24 * 60 * 60 * 1000;
const expiresAt = new Date(Date.now() + TTL_MS).toISOString();

return [{
  json: {
    success: true,
    message: 'Login successful.',
    expiresAt,
    user: {
      id: dbResult.id,
      name: dbResult.name,
      email: dbResult.email,
      role: dbResult.role,
      theme_header_color: dbResult.theme_header_color,
      theme_main_color: dbResult.theme_main_color,
      theme_accent_color: dbResult.theme_accent_color
    }
  }
}];

