WITH cleanup AS (
  DELETE FROM sessions WHERE expires_at < now() RETURNING 1
), cleared AS (
  DELETE FROM login_attempts WHERE (kind = 'login' AND key = $3) OR created_at < now() - interval '1 day' RETURNING 1
)
INSERT INTO sessions (token, user_id, expires_at)
VALUES (replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), $1, $2)
RETURNING token;

